<template><section><div class="page-header"><div><p class="eyebrow">Schedule</p><h1>Availability</h1><p class="lede">Open only the hours you can reliably keep. Changes persist instantly in this private workspace.</p></div><span class="timezone-label">Timezone: {{ workspace.timezone }}</span></div><div class="card availability-card"><div class="table-head"><span>Day</span><span>Hours</span><span>Open</span></div><div v-for="day in workspace.availability" :key="day.day" class="day-row"><strong>{{ day.day }}</strong><div class="time-fields"><input :aria-label="day.day + ' start time'" type="time" v-model="day.start" :disabled="!day.active" @change="save" /><span>to</span><input :aria-label="day.day + ' end time'" type="time" v-model="day.end" :disabled="!day.active" @change="save" /></div><label class="switch"><input type="checkbox" v-model="day.active" @change="save" /><span aria-hidden="true"></span><b>{{ day.active ? 'Active' : 'Closed' }}</b></label></div></div><p class="save-note" role="status">{{ saved ? 'Saved to workspace.' : 'Toggle a day or adjust an interval to save.' }}</p></section></template>
<script setup>import { inject, ref } from 'vue'; const workspace=inject('workspace'),saved=ref(false); function save(){saved.value=true;setTimeout(()=>saved.value=false,1800)}</script>
<style scoped>.timezone-label{color:var(--muted);font-size:13px}.availability-card{padding:0;overflow:hidden;box-sizing:border-box;min-width:0}.table-head,.day-row{display:grid;grid-template-columns:1fr 2fr 130px;align-items:center;gap:18px;padding:16px 22px;box-sizing:border-box;min-width:0}.table-head{color:var(--muted);font-size:12px;font-weight:800;text-transform:uppercase;letter-spacing:.06em;background:#fbfcfd;border-bottom:1px solid var(--border)}.day-row{min-height:76px;border-bottom:1px solid var(--border)}.day-row:last-child{border-bottom:0}.time-fields{display:flex;align-items:center;gap:10px;box-sizing:border-box;min-width:0}.time-fields input{max-width:145px;min-width:0;box-sizing:border-box;padding:0 9px}.switch{display:flex;align-items:center;gap:9px;cursor:pointer;box-sizing:border-box;min-width:0}.switch input{position:absolute;opacity:0;width:0;height:0;pointer-events:none}.switch span{width:38px;height:22px;border-radius:20px;background:#aeb8c5;position:relative;box-sizing:border-box;flex:0 0 auto}.switch span:after{content:'';position:absolute;width:16px;height:16px;left:3px;top:3px;background:#fff;border-radius:50%;transition:.15s}.switch input:checked+span{background:var(--accent)}.switch input:checked+span:after{left:19px}.switch b{font-size:13px}.save-note{color:var(--success);font-size:13px;min-height:22px}@media(max-width:650px){.table-head{display:none}.day-row{grid-template-columns:1fr;gap:10px;padding:17px}.time-fields input{max-width:none;flex:1}.switch{margin-top:2px}}</style>